int search(const std::vector<int>& a, int target) {
  int left = 0, right = static_cast<int>(a.size());
  while (left <= right) {
    int mid = (left + right) / 2;
    if (a[mid] == target) return mid;
    if (a[mid] < target) left = mid + 1; else right = mid - 1;
  }
  return -1;
}

